import React, { useState, useEffect, useCallback } from 'react';

const Ahorro = ({ user }) => {
    const [saveForm, setSaveForm] = useState({
        hasSpecificGoal: false,
        targetAmount: 'No especificado',
        weeklySavings: 'No especificado'
    });
    const [loading, setLoading] = useState(true);

    const fetchFormData = useCallback(async (formType) => {
        if (!user || !user._id) {
            console.warn('El usuario no está definido o no tiene un _id');
            return;
        }

        try {
            const response = await fetch(`http://localhost:5000/api/forms/${formType}/get${capitalize(formType)}/${user._id}`);
            const result = await response.json();
            console.log('Datos obtenidos de la API:', result); // Imprimir resultado
            // Asegúrate de que la respuesta tenga las propiedades correctas
            if (result) {
                setSaveForm({
                    hasSpecificGoal: result.hasSpecificGoal || false,
                    targetAmount: result.targetAmount || 'No especificado',
                    weeklySavings: result.weeklySavings || 'No especificado'
                });
            }
        } catch (error) {
            console.error(`Error fetching ${formType} form data:`, error);
        } finally {
            setLoading(false); // Finaliza el loading
        }
    }, [user]);

    useEffect(() => {
        fetchFormData('save');
    }, [fetchFormData]);

    const capitalize = (string) => string.charAt(0).toUpperCase() + string.slice(1);

    if (loading) {
        return <div>Cargando...</div>; // Mostrar un mensaje de carga
    }

    return (
        <div className="ahorro-container">
            <h1 className="ahorro-title">Ahorro</h1>
            <div className="ahorro-content">
                <h3>Datos Ahorro</h3>
                <p>Tiene Meta Específica: {saveForm.hasSpecificGoal ? 'Sí' : 'No'}</p>
                <p>Monto Objetivo: {saveForm.targetAmount}</p>
                <p>Ahorros Semanales: {saveForm.weeklySavings}</p>
            </div>
        </div>
    );
};

export default Ahorro;
